using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.TwistedGround.Signed;

internal sealed class CandidateSourceDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Signed Gaussian Candidates",
        H("Signed Gaussian Candidates"),
        Blocks(
            Paragraph(Text("The signed candidates use the original mode sources and period correction. The normalized source roots are defined through a single complex power on a right half-plane, so their real parts are positive. Their sum cannot vanish. The four rational T denominators follow from the original square-root bidisk bounds.")),
            Describe.Lean(DescribeId.Create("h-ne-zero"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.h_ne_zero"), H("h_ne_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For either Boolean label and complex u,r with norm(u)+norm(r)<1, the signed source factor h(e,u,r) is nonzero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("source-u"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.source_u"), H("source_u"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The derivative in u of the actual sourceMode(e,u,r) is mLog(e,u,r) times that source, on norm(u)+norm(r)<1."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("source-frequency"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.source_frequency"), H("source_frequency"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For nonzero b(u) and h(e,u,r), the original signed first-order source operator has frequency modeA(e,u,r)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("w-square"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.W_square"), H("W_square"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The square of W(e,u,r) equals h(e,u,r)/b(u) on the source disk."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("source-w-normalization"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.source_W_normalization"), H("source_W_normalization"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The product sourceMode(e,u,r)*b(u)*W(e,u,r) equals one on the source disk."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("w-sum-ne-zero"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.W_sum_ne_zero"), H("W_sum_ne_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For any labels and complex u,v,r in the two source disks, W(e,u,r)+W(f,v,r) is nonzero. Each normalized root has positive real part."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("ell-eq-source"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.ell_eq_source"), H("ell_eq_source"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For norm(r)<1, ell(r) is the original shiftedCentralDerivative(r,0) divided by period(r)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("e-ne-zero"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.E_ne_zero"), H("E_ne_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For either pair of labels, E(e,f,u,v,r) is nonzero when norm(u)+sqrt(norm(r))<1 and norm(v)+sqrt(norm(r))<1. These stronger square-root bounds control all four denominators."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-small"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.original_small"), H("original_small"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For real 0<=r<1, norm(w)+sqrt(r)<1 implies norm(w)+norm((r:Complex))<1."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("candidatet-original-displacement"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.candidateT_original_displacement"), H("candidateT_original_displacement"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For real 0<r<1 on the original source bidisk, the signed T candidate satisfies the exact original spatial displacement equation with original modeA, modeH and central period ratio. All denominator conditions follow from the domain."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("candidatej-joint-analytic"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.candidateJ_joint_analytic"), H("candidateJ_joint_analytic"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The signed J candidate is jointly complex analytic in u,v on the two source disks. Its normalized-root denominator never vanishes, including equal coordinates."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("candidates-original-joint-differentiable"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.candidates_original_joint_differentiable"), H("candidates_original_joint_differentiable"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For real 0<r<1 on the source bidisk, both signed candidates are jointly complex differentiable in u,v, for all four label pairs."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("candidatej-diagonal"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/Signed/CandidateSource.candidateJ_diagonal"), H("candidateJ_diagonal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("At equal coordinates the signed J candidate is (r/4-correction(r))/(b(u)*h(e,u,r)) plus r squared*u divided by eight times (b(u)*h(e,u,r)) squared. The identity includes u=0."))), DescribeRole.Theorem)
        )));
}
